#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_node_nonzero_ct_zero_wt_nonzero_tat(void) {
    // Setup: Build a linked list with at least two nodes.
    // We need the target node NOT to be the head, and we need to traverse.
    // Path conditions:
    // 1. Head node exists and its ID != id (so we skip the first if block).
    // 2. ct != 0 (so we update CT).
    // 3. wt == 0 (so we skip WT update).
    // 4. tat != 0 (so we update TAT).
    // The path also shows we exit the while loop (ptr != NULL && ptr->ID != id) -> FOR_EXIT,
    // meaning we find the node.

    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;

    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial values are zero (as set by insert).
    node *ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Test: Update node with ID 2 (non-head) with ct=100, wt=0, tat=200.
    update(&root, 2, 100, 0, 200);

    // Assert: Only CT and TAT should be updated, WT remains zero.
    ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(100, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(200, ptr->TAT);

    // Also verify other nodes unchanged (head node ID 1 should still have zeros).
    ptr = root; // head
    TEST_ASSERT_EQUAL_INT(1, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_update_non_head_node_nonzero_ct_zero_wt_nonzero_tat);
    return UNITY_END();
}

